/** Focused native setup/live journey. Draft settings commit only when tracking starts. */
public final class TrackingActivity extends Activity {
    interface Commands {TrackingService.Snapshot snapshot();void start(TrackingActivity owner,Intent intent);void command(TrackingActivity owner,Intent intent);void review(TrackingActivity owner);}
    static Commands commands=new Commands(){public TrackingService.Snapshot snapshot(){return TrackingService.snapshot();}public void start(TrackingActivity owner,Intent intent){owner.startForegroundService(intent);}public void command(TrackingActivity owner,Intent intent){owner.startService(intent);}public void review(TrackingActivity owner){owner.reviewDefault();}};
    static TrackingService.StoreFactory stores=Store::new;
    private Commands runtime;private boolean sonar,sonarAnalysis,resumed,resumeAfterFocus;private SonarSignalChart sonarChart;
    private Store store;private boolean mic,clips,light,sawLive,startRequested,updatingSwitch,finishingFlow;private String rendered="",setupIssue="";private long lastGraph;
    private TextView elapsed,status,subtitle,movementValue,soundValue,error,micHelp,audioIssue;private Button primary;private LinearLayout graph;private RecordChart chart;private Switch microphone;
    private final Handler poller=new Handler(Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){refresh();poller.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);if(getIntent().getBooleanExtra("visualReview",false))getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);runtime=commands;store=stores.open(this);
        if(runtime.snapshot()==null){store.recoverInterrupted();Prefs.of(this).edit().putBoolean("tracking",false).putBoolean("trackingPaused",false).apply();}
        sonar=saved==null?"sonar".equals(getIntent().getStringExtra("sensor")):saved.getBoolean("sonar");sonarAnalysis=saved!=null&&saved.getBoolean("sonarAnalysis");setupIssue=saved==null?"":saved.getString("setupIssue","");
        mic=saved==null?Prefs.flag(this,"noiseEnabled"):saved.getBoolean("mic");clips=saved==null?Prefs.flag(this,"saveClips"):saved.getBoolean("clips");light=saved==null?Prefs.of(this).getBoolean("recordLight",true):saved.getBoolean("light");
        if(runtime.snapshot()!=null){TrackingService.Snapshot snapshot=runtime.snapshot();if(snapshot!=null&&snapshot.phase.equals("ARMED"))armed(snapshot);else{sawLive=true;live(snapshot);}}else setup();
    }
    @Override protected void onResume(){super.onResume();resumed=true;if(rendered.equals("SETUP")&&runtime.snapshot()==null)setup();if(TrackingService.RESUME.equals(getIntent().getAction())){getIntent().setAction(null);TrackingService.Snapshot current=runtime.snapshot();if(current!=null&&current.sonar)resumeAfterFocus=true;else command(TrackingService.RESUME);}poller.removeCallbacks(tick);poller.post(tick);}
    @Override protected void onPostResume(){super.onPostResume();Design.systemBars(this,true);getWindow().getDecorView().post(()->{if(!isDestroyed()&&hasWindowFocus())Design.systemBars(this,true);});}
    @Override protected void onPause(){resumed=false;poller.removeCallbacks(tick);super.onPause();}
    @Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putBoolean("sonar",sonar);b.putBoolean("sonarAnalysis",sonarAnalysis);b.putBoolean("mic",mic);b.putBoolean("clips",clips);b.putBoolean("light",light);b.putString("setupIssue",setupIssue);}
    private TextView text(LinearLayout p,String copy,int size,int weight,int color){return Design.text(p,copy,size,weight,color);}
    private void line(LinearLayout body){View v=new View(this);v.setBackgroundColor(0xff62566d);body.addView(v,new LinearLayout.LayoutParams(-1,Design.dp(this,1)));}
    private void heading(LinearLayout body,String copy){Design.space(body,10);text(body,copy,13,600,Design.LILAC);Design.space(body,8);}
    private Button action(LinearLayout parent,String title,boolean filled,Runnable click){Button b=Design.button(parent,title,false,click);b.setTextColor(filled?Design.PLUM:Design.CREAM);GradientDrawable background=Design.shape(this,filled?Design.LILAC:Color.TRANSPARENT,17);if(!filled)background.setStroke(Design.dp(this,1),0xff8c7c9d);b.setBackground(Appearance.reduced(this)?background:new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x334a2615),background,null));
        String icon=title.startsWith("Pause")?"pause":title.startsWith("Resume")?"play":title.startsWith("Stop")?"stop":null;if(icon!=null){int size=Design.dp(this,20);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(size,size,android.graphics.Bitmap.Config.ARGB_8888);Design.Icon glyph=new Design.Icon(this,icon,filled?Design.PLUM:Design.CREAM);glyph.layout(0,0,size,size);glyph.draw(new android.graphics.Canvas(bitmap));android.graphics.drawable.BitmapDrawable drawable=new android.graphics.drawable.BitmapDrawable(getResources(),bitmap);drawable.setBounds(0,0,size,size);android.text.SpannableString label=new android.text.SpannableString("\uFFFC   "+title);label.setSpan(new android.text.style.ImageSpan(drawable,android.text.style.ImageSpan.ALIGN_CENTER),0,1,0);b.setText(label);b.setContentDescription(title);}return b;}
    private LinearLayout footer(LinearLayout body){LinearLayout root=(LinearLayout)body.getParent().getParent();LinearLayout footer=Design.col(this);footer.setPadding(Design.dp(this,24),0,Design.dp(this,24),Design.dp(this,16));root.addView(footer,new LinearLayout.LayoutParams(-1,-2));return footer;}
    private void setup(){rendered="SETUP";LinearLayout body=Design.darkPage(this);Design.pad(body,24,8);
        LinearLayout header=Design.row(this);View back=Design.iconButton(this,"back","Back",this::finish);((Design.Icon)back).tint(Design.CREAM);header.addView(back,new LinearLayout.LayoutParams(Design.dp(this,42),Design.dp(this,48)));header.addView(Design.text(this,"Tracking setup",23,600,Design.CREAM));body.addView(header);
        heading(body,"Choose sensor");boolean available=getSystemService(SensorManager.class).getDefaultSensor(Sensor.TYPE_ACCELEROMETER)!=null;
        sensor(body,"phone","Phone movement",available?motionHelp():"No accelerometer is available on this phone.",!sonar,true);
        Design.space(body,8);sensor(body,"sonar","Contactless sonar","Bedside echo sensing · microphone required",sonar,false);Design.space(body,12);line(body);
        heading(body,"Phone placement");if(sonar){text(body,"Stable bedside surface · speaker toward your body",15,600,Design.CREAM);Design.space(body,8);text(body,"Keep the phone uncovered and charging. Do not use headphones.",12,400,Design.LILAC);Design.space(body,12);}else{ImageView placement=new ImageView(this);placement.setImageResource(R.drawable.tracking_placement);placement.setScaleType(ImageView.ScaleType.CENTER_CROP);placement.setBackground(Design.shape(this,Design.PLUM,16));placement.setClipToOutline(true);placement.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);body.addView(placement,new LinearLayout.LayoutParams(-1,Design.dp(this,118)));Design.space(body,8);
        LinearLayout guidance=Design.row(this);Design.Icon check=new Design.Icon(this,"check",Design.PLUM);check.setPadding(Design.dp(this,5),Design.dp(this,5),Design.dp(this,5),Design.dp(this,5));check.setBackground(Design.shape(this,Design.LILAC,20));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(Design.dp(this,28),Design.dp(this,28));cp.rightMargin=Design.dp(this,16);guidance.addView(check,cp);LinearLayout copy=Design.col(this);text(copy,"On mattress, uncovered",14,600,Design.CREAM);Design.space(copy,5);text(copy,"Keep your phone on the bed surface, not under a pillow or blanket.",12,400,Design.LILAC);guidance.addView(copy,new LinearLayout.LayoutParams(0,-2,1));body.addView(guidance);Design.space(body,12);}line(body);
        heading(body,"Additional sensors");microphone=toggle(body,"mic",sonar?"Analyze sleep sounds":"Record sounds",sonar?sonarAnalysis:mic,on->{if(updatingSwitch)return;if(sonar){sonarAnalysis=on;if(micHelp!=null)micHelp.setText(sonarSoundHelp());return;}if(!on){setMic(false);return;}chooseMicrophone();});line(body);
        boolean lightAvailable=getSystemService(SensorManager.class).getDefaultSensor(Sensor.TYPE_LIGHT)!=null;if(!lightAvailable)light=false;Switch brightness=toggle(body,"sun",sonar?"Light recording unavailable":lightAvailable?"Record light levels":"Light sensor unavailable",sonar?false:light,on->light=on);brightness.setEnabled(lightAvailable&&!sonar);brightness.setAlpha(lightAvailable&&!sonar?1f:.45f);Design.space(body,8);micHelp=text(body,sonar?sonarSoundHelp():mic?(clips?"Sound estimates and clips stay on this phone.":"Sound analysis only · saving audio clips is off."):"Microphone is optional. Movement works with it off.",11,400,Design.LILAC);Design.space(body,12);line(body);
        heading(body,"Automatic tracking");Button automatic=action(body,"Choose automatic start",false,()->startActivityForResult(new Intent(this,AutomaticTrackingActivity.class),92));automatic.setContentDescription("Choose automatic start");automatic.setEnabled(!sonar);automatic.setAlpha(sonar?.45f:1f);if(sonar)text(body,"Automatic starts remain phone-movement only.",11,400,Design.LILAC);
        error=text(body,setupIssue,12,500,0xffffd495);error.setVisibility(setupIssue.isEmpty()?View.GONE:View.VISIBLE);Design.space(body,4);primary=action(footer(body),"Start tracking  →",true,this::start);primary.setEnabled(sonar||available);if(!sonar&&!available)showError("Movement tracking needs a working accelerometer.");
    }
    private void sensor(LinearLayout body,String icon,String title,String help,boolean selected,boolean movement){
        LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,movement?80:66));Design.pad(row,14,10);GradientDrawable background=Design.shape(this,selected?0xff3a3046:Color.TRANSPARENT,16);background.setStroke(Design.dp(this,1),selected?Design.VIOLET:0xff51485e);row.setBackground(background);
        RadioButton radio=new RadioButton(this);radio.setChecked(selected);radio.setButtonTintList(android.content.res.ColorStateList.valueOf(selected?Design.LILAC:0xff9786aa));radio.setClickable(false);radio.setFocusable(false);radio.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);row.addView(radio,new LinearLayout.LayoutParams(Design.dp(this,32),Design.dp(this,40)));
        Design.Icon glyph=new Design.Icon(this,icon,selected?Design.LILAC:0xff9786aa);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(this,32),Design.dp(this,32));ip.setMargins(Design.dp(this,8),0,Design.dp(this,14),0);row.addView(glyph,ip);LinearLayout words=Design.col(this);text(words,title,15,600,selected?Design.CREAM:Design.LILAC);Design.space(words,4);text(words,help,11,400,Design.LILAC);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));row.setSelected(selected);row.setContentDescription(title+(selected?" selected":""));row.setOnClickListener(v->{if(movement){if(sonar){sonar=false;showError("");setup();}else startActivity(RecordUi.intent(this,MotionSensorActivity.class));}else openSonar();});body.addView(row);
    }
    private void openSonar(){startActivityForResult(RecordUi.intent(this,ContactlessSetupActivity.class),93);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==93&&result==RESULT_OK){try{SonarSettings.load(this);sonar=true;showError("");setup();}catch(RuntimeException invalid){showError(invalid.getMessage());}}}
    private String motionHelp(){try{return "On-bed motion · "+MotionSettings.load(this).label()+" sensitivity. Tap to configure.";}catch(Exception e){return "Review motion sensor settings.";}}
    private Switch toggle(LinearLayout body,String icon,String title,boolean checked,java.util.function.Consumer<Boolean> change){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,48));Design.Icon glyph=new Design.Icon(this,icon,Design.CREAM);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(this,26),Design.dp(this,26));ip.rightMargin=Design.dp(this,18);row.addView(glyph,ip);row.addView(Design.text(this,title,15,500,Design.CREAM),new LinearLayout.LayoutParams(0,-2,1));Switch s=new Switch(this);Design.styleSwitch(this,s,Design.VIOLET,0xff655a71);s.setContentDescription(title);s.setChecked(checked);s.setOnCheckedChangeListener((v,on)->{change.accept(on);if(Appearance.reduced(this))s.jumpDrawablesToCurrentState();});row.addView(s);body.addView(row);return s;}
    private String sonarSoundHelp(){return sonarAnalysis?"This night only · estimates, no clips or snoring cues.":"Off for this night. Contactless sensing still uses the microphone.";}
    private String soundIssue(String issue){return switch(issue){case "queue"->"analysis could not keep up";case "model"->"model unavailable";case "storage"->"could not save estimates";case "cleanup"->"cleanup needs attention";case "limit"->"event limit reached; later estimates were not saved";default->"capture interrupted";};}
    private void chooseMicrophone(){new AlertDialog.Builder(this).setTitle("Use the microphone?").setMessage("Estimate snoring and speech on this phone. You can also save short sound clips privately. Estimates can be wrong.").setPositiveButton("Analyze & save clips",(d,w)->enableMicrophone(true)).setNegativeButton("Analysis only",(d,w)->enableMicrophone(false)).setNeutralButton("Cancel",(d,w)->setMic(false)).setOnCancelListener(d->setMic(false)).show();}
    private void setMic(boolean on){mic=on;updatingSwitch=true;if(microphone!=null)microphone.setChecked(on);updatingSwitch=false;if(micHelp!=null)micHelp.setText(mic?(clips?"Sound estimates and clips stay on this phone.":"Sound analysis only · saving audio clips is off."):"Microphone is optional. Movement works with it off.");}
    private void enableMicrophone(boolean save){clips=save;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)setMic(true);else{setMic(false);requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},80);}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==80){setMic(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED);if(!mic&&error!=null)showError("Microphone was not allowed. You can still use movement tracking.");}}
    private void showError(String message){setupIssue=message==null?"Tracking could not start. Try again.":message;if(error!=null){error.setText(setupIssue);error.setVisibility(setupIssue.isEmpty()?View.GONE:View.VISIBLE);}}
    private void start(){
        if(startRequested)return;showError("");
        if(sonar){
            if(!resumed||!hasWindowFocus())return;
            try{if(SonarSettings.factory.open(this).getString("profile","").isEmpty())throw new IllegalStateException("Test the contactless sensor first.");SonarConfig config=SonarSettings.load(this);SonarCapabilities caps=SonarCapabilities.provider.read(this);if(!caps.microphone)throw new IllegalStateException("Allow microphone access in contactless setup first.");if(!caps.allowed())throw new IllegalStateException(caps.issue);SonarEntry.Ticket admission=SonarEntry.issue(true,SystemClock.elapsedRealtime(),0,config,sonarAnalysis);primary.setEnabled(false);primary.setText("Starting…");startRequested=true;runtime.start(this,new Intent(this,TrackingService.class).setAction(TrackingService.SONAR).putExtra("sonarAdmission",admission.nonce));}catch(RuntimeException failure){startRequested=false;primary.setEnabled(true);primary.setText("Start tracking  →");showError(failure.getMessage());}return;
        }
        if(mic&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){setMic(false);showError("Microphone permission is unavailable. Start again for movement only.");return;}
        Prefs.of(this).edit().putBoolean("noiseEnabled",mic).putBoolean("saveClips",mic&&clips).putBoolean("recordLight",light).apply();primary.setEnabled(false);primary.setText("Starting…");startRequested=true;
        try{runtime.start(this,new Intent(this,TrackingService.class));}catch(Exception e){startRequested=false;primary.setEnabled(true);primary.setText("Start tracking  →");showError("Tracking could not start: "+e.getMessage());}
    }
    private void command(String action){try{Intent intent=new Intent(this,TrackingService.class).setAction(action);TrackingService.Snapshot current=runtime.snapshot();if(TrackingService.RESUME.equals(action)&&current!=null&&current.sonar){if(!resumed||!hasWindowFocus())return;SonarEntry.Ticket admission=SonarEntry.issue(true,SystemClock.elapsedRealtime(),current.id,new SonarConfig(current.sonarGain),current.soundsRequested);intent.putExtra("sonarAdmission",admission.nonce);}runtime.command(this,intent);}catch(Exception e){Ui.toast(this,"Could not change tracking: "+e.getMessage());}}
    private static String duration(long milliseconds){long seconds=Math.max(0,milliseconds/1000);return seconds>=3600?seconds/3600+" h "+seconds/60%60+" min":seconds>=60?seconds/60+" min "+seconds%60+" sec":seconds+" sec";}
    private void live(TrackingService.Snapshot s){if(s==null)return;rendered=s.phase;sawLive=true;LinearLayout body=Design.darkPage(this);Design.pad(body,24,16);
        Design.space(body,4);LinearLayout orb=Design.row(this);orb.setGravity(Gravity.CENTER);Design.Icon moon=new Design.Icon(this,s.paused()?"pause":"tracking",Design.VIOLET);orb.addView(moon,new LinearLayout.LayoutParams(Design.dp(this,30),Design.dp(this,30)));body.addView(orb);Design.space(body,10);
        status=text(body,s.paused()?"Tracking paused":s.phase.equals("ACTIVE")?(s.sonar?"Contactless tracking":"Tracking sleep"):s.sonar&&s.phase.equals("STARTING")?"Preparing contactless sensor":"Updating tracking…",24,600,Design.LILAC);status.setGravity(Gravity.CENTER);Design.space(body,8);subtitle=text(body,s.paused()?"Sensors and microphone are stopped":s.phase.equals("ACTIVE")?(s.sonar?"Bedside echo change · not sleep stages":"Keep your phone in place"):s.sonar&&s.phase.equals("STARTING")?"Checking actual built-in audio routes":"Stopping sensors and microphone…",13,400,Design.LILAC);subtitle.setGravity(Gravity.CENTER);Design.space(body,20);
        elapsed=text(body,duration(s.active),58,700,Design.LILAC);elapsed.setGravity(Gravity.CENTER);Design.space(body,8);text(body,"Started "+RecordUi.clock(this,s.start,java.time.ZoneId.systemDefault()),14,400,Design.LILAC).setGravity(Gravity.CENTER);Design.space(body,16);line(body);
        Alarm next=null;long soon=Long.MAX_VALUE;for(Alarm alarm:store.alarms())if(alarm.enabled&&!alarm.skipInvalid){long when=Prefs.of(this).getLong("deadline_"+alarm.id,alarm.next(System.currentTimeMillis()));if(when>0&&when<soon){soon=when;next=alarm;}}
        liveRow(body,"alarm","Next alarm",next==null?"No alarm set":AlarmEditorActivity.displayTime(this,next),true);line(body);Design.space(body,8);movementValue=liveRow(body,"report",s.sonar?"Contactless movement":"Movement (phone motion)","",false);soundValue=liveRow(body,"mic","Sound recording","",false);audioIssue=text(body,"",12,500,0xffffd495);audioIssue.setVisibility(View.GONE);Design.space(body,10);line(body);heading(body,s.sonar?"Relative echo change":"Movement activity");text(body,s.sonar?"Actual signal · quality gaps stay blank":s.paused()?"Minute averages · paused time excluded":"Live signal · saved as minute averages",11,400,Design.LILAC);Design.space(body,4);chart=null;sonarChart=null;graph=Design.col(this);body.addView(graph,new LinearLayout.LayoutParams(-1,Design.dp(this,150)));
        if(TravelCues.control.manual()!=null){Design.space(body,12);action(body,"Review travel light cues",false,()->startActivity(RecordUi.intent(this,TravelCueReviewActivity.class)));}
        LinearLayout footer=footer(body);boolean ready=s.phase.equals("ACTIVE")||s.paused();primary=action(footer,s.paused()?"Resume tracking":"Pause tracking",true,()->command(s.paused()?TrackingService.RESUME:TrackingService.PAUSE));primary.setEnabled(ready);
        Button stop=action(footer,"Stop tracking",false,this::confirmStop);stop.setEnabled(s.sonar?!s.phase.equals("CLOSED"):ready);if(s.sonar&&s.phase.equals("BLOCKED"))action(body,"Open app settings",false,()->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));lastGraph=0;update(s);
    }
    private void confirmStop(){AlertDialog dialog=new AlertDialog.Builder(this).setTitle("End this recording?").setMessage("Save this session and view its report. Paused time is excluded.").setPositiveButton("End & review",(d,w)->command(TrackingService.STOP)).setNegativeButton("Keep tracking",null).create();dialog.show();ReportDialogs.style(dialog);}
    private TextView liveRow(LinearLayout body,String icon,String title,String value,boolean large){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,large?72:48));Design.Icon glyph=new Design.Icon(this,icon,Design.LILAC);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(this,26),Design.dp(this,26));ip.rightMargin=Design.dp(this,18);row.addView(glyph,ip);if(large){LinearLayout copy=Design.col(this);text(copy,title,12,400,Design.CREAM);Design.space(copy,6);TextView label=text(copy,value,22,600,Design.CREAM);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));body.addView(row);return label;}row.addView(Design.text(this,title,14,500,Design.CREAM),new LinearLayout.LayoutParams(0,-2,1));TextView label=Design.text(this,value,14,500,Design.LILAC);label.setGravity(Gravity.END);row.addView(label);body.addView(row);return label;}
    private void update(TrackingService.Snapshot s){String value=duration(s.active);android.text.SpannableString span=new android.text.SpannableString(value);java.util.regex.Matcher units=java.util.regex.Pattern.compile("h|min|sec").matcher(value);while(units.find())span.setSpan(new android.text.style.RelativeSizeSpan(.5f),units.start(),units.end(),0);elapsed.setText(span);if(s.sonar){movementValue.setText(s.paused()?"Paused":s.sonarReadings.isEmpty()?"Calibrating":s.sonarReadings.get(s.sonarReadings.size()-1).quality==SonarFrame.Quality.VALID?"Measured":"Signal missing");soundValue.setText(!s.soundsRequested?"Off":s.paused()?"Paused":s.soundAnalysis==null?"Preparing":s.soundAnalysis.state.equals("error")?"Needs attention":s.soundAnalysis.frames>0?"Analysis only":"Preparing");String soundIssue=s.soundAnalysis!=null&&!s.soundAnalysis.issue.isEmpty()?"Sound analysis stopped · "+soundIssue(s.soundAnalysis.issue):"";String issue=s.sonarError+(s.sonarError.isEmpty()||soundIssue.isEmpty()?"":"\n")+soundIssue;audioIssue.setText(issue);audioIssue.setVisibility(issue.isEmpty()?View.GONE:View.VISIBLE);if(sonarChart==null){sonarChart=new SonarSignalChart(this);graph.addView(sonarChart,new LinearLayout.LayoutParams(-1,-1));}sonarChart.data(s.sonarReadings);return;}movementValue.setText(s.paused()?"Paused":s.motion?(s.samples>0?"On":"Collecting"):"Unavailable");soundValue.setText(s.automatic?(!s.soundsRequested?"Off":s.paused()?"Paused":s.mic?(s.keepClips?"On":"Analysis only"):"Unavailable"):!Prefs.flag(this,"noiseEnabled")?"Off":s.paused()?"Paused":s.mic?(Prefs.flag(this,"saveClips")?"On":"Analysis only"):Prefs.flag(this,"noiseEnabled")?"Unavailable":"Off");
        String issue=Prefs.text(this,"audioError","");boolean wanted=s.automatic?s.soundsRequested:Prefs.flag(this,"noiseEnabled");boolean showIssue=wanted&&!issue.isEmpty();if(audioIssue!=null){audioIssue.setText(showIssue?"Sound needs attention: "+issue:"");audioIssue.setVisibility(showIssue?View.VISIBLE:View.GONE);}
        if(SystemClock.elapsedRealtime()-lastGraph>=1000){lastGraph=SystemClock.elapsedRealtime();List<JSONObject> data=store.rows("SELECT * FROM epochs WHERE session=? ORDER BY time",""+s.id);long now=s.now;if(!s.paused())data.addAll(s.readings);if(chart==null){chart=new RecordChart(this,data,"movement",s.start,Math.max(s.start+1,now),true);graph.addView(chart,new LinearLayout.LayoutParams(-1,-1));}else chart.updateData(data,now);}
    }
    private void armed(TrackingService.Snapshot s){rendered="ARMED";LinearLayout body=Design.darkPage(this);Design.pad(body,24,20);Design.space(body,24);status=text(body,"Waiting to track",28,600,Design.LILAC);Design.space(body,16);subtitle=text(body,"",16,400,Design.CREAM);Design.space(body,24);text(body,"Screen off · phone on the mattress",16,600,Design.LILAC);Design.space(body,12);text(body,"Phone stillness is an estimate. Waiting is limited to four hours; no sleep record is created until recording starts.",13,400,Design.LILAC);Design.space(body,20);text(body,s.soundsRequested?"Sound recording begins when tracking starts. Sleep sounds stay off.":"Microphone and sleep sounds stay off.",13,400,Design.LILAC);action(footer(body),"Cancel automatic start",true,()->{command(TrackingService.STOP);});updateArmed(s);}
    private void updateArmed(TrackingService.Snapshot s){subtitle.setText(s.automaticState.equals("SCREEN_IN_USE")?"Waiting for the screen to turn off":s.automaticState.equals("QUIET")?"Still for "+duration(s.quietMillis)+" / 15 min":s.automaticState.equals("COLLECTING")?"Waiting for a continuous movement signal":"Waiting for your selected start time");}
    private void refresh(){TrackingService.Snapshot s=runtime.snapshot();if(s!=null){if(s.phase.equals("ARMED")){if(!rendered.equals("ARMED"))armed(s);else updateArmed(s);return;}if(!rendered.equals(s.phase))live(s);else if(!rendered.equals("SETUP"))update(s);return;}if(rendered.equals("ARMED")){setup();return;}if(sawLive){if(finishingFlow)return;finishingFlow=true;String failure=Prefs.text(this,"trackingError","");if(failure.isEmpty())finishRecording();else new AlertDialog.Builder(this).setTitle("Recording needs attention").setMessage(failure).setPositiveButton("View records",(d,w)->finishRecording()).setCancelable(false).show();}else if(startRequested){startRequested=false;primary.setEnabled(true);primary.setText("Start tracking  →");showError(Prefs.text(this,"trackingError","Tracking did not start. Try again."));}else if(getIntent().getBooleanExtra("automaticRequest",false)){String failure=Prefs.text(this,"trackingError","");if(!failure.isEmpty())showError(failure);}}
    private void finishRecording(){setResult(RESULT_OK);runtime.review(this);}
    private void reviewDefault(){setResult(RESULT_OK);if(isTaskRoot())startActivity(new Intent(this,MainActivity.class).putExtra("showReport",true));finish();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused){Design.focusedSystemBars(this,true);if(resumed&&resumeAfterFocus){resumeAfterFocus=false;command(TrackingService.RESUME);}}}
    @Override protected void onDestroy(){poller.removeCallbacks(tick);if(store!=null)store.close();super.onDestroy();}
}
